#include <stdio.h>

int count_above(int fish[], int count, int limit) {
    int n = 0;
    for (int i = 0; i < count; i++) {
        if (fish[i] > limit) {
            n++;
        }
    }
    return n;
}

int main(void) {
    int fish[4] = { {a}, {b}, {c}, {d} };
    printf("超过 {lim} 条的有 %d 碗\n", count_above(fish, 4, {lim}));
    printf("只有一碗时：%d 碗\n", count_above(fish, 1, {lim}));
    return 0;
}
